#!/usr/bin/env node
// Generates supabase/tests/database/07_money_rounding_mirror.test.sql from
// supabase/tests/fixtures/money-conversion-cases.json -- the single fixture
// that proves src/engine/money (Jest) and the SQL mirror (plan 01-05,
// 20260924000500_fx_stamping.sql) round every case identically (D-16).
//
// Default mode: (re)writes the generated file.
// --check mode: regenerates in memory and exits 1 with a diff-style message
// if the file on disk differs -- used by CI (plan 01-06) to catch drift
// between the fixture and the checked-in generated file.

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');
const FIXTURE_PATH = join(ROOT, 'supabase/tests/fixtures/money-conversion-cases.json');
const OUTPUT_PATH = join(ROOT, 'supabase/tests/database/07_money_rounding_mirror.test.sql');

// pgTAP test names are single-quoted SQL string literals; escape any single
// quote in a fixture's case name by doubling it, the standard SQL escape.
function sqlLiteral(s) {
  return `'${String(s).replace(/'/g, "''")}'`;
}

function sqlString(s) {
  // Same escaping, for a value quoted as SQL text (e.g. an expected numeric
  // string compared via ::text), not a test-name literal -- kept as a
  // separate function so the two call sites stay self-documenting.
  return sqlLiteral(s);
}

function generate(fixture) {
  const halfUp = fixture.halfUp ?? [];
  const convert = fixture.convert ?? [];
  const convertExact = fixture.convertExact ?? [];
  const customPerEur = fixture.customPerEur ?? [];
  const crossRate = fixture.crossRate ?? [];
  const exponents = fixture.exponents ?? [];

  const total =
    halfUp.length + convert.length + convertExact.length + customPerEur.length + crossRate.length + exponents.length;

  const lines = [];
  lines.push(
    '-- GENERATED by scripts/gen-money-mirror-test.mjs from supabase/tests/fixtures/money-conversion-cases.json.'
  );
  lines.push('-- Do not edit by hand. Mirrors src/engine/money (D-16).');
  lines.push('');
  lines.push('begin;');
  lines.push('create extension if not exists pgtap with schema extensions;');
  lines.push('');
  lines.push(`select extensions.plan(${total});`);
  lines.push('');

  for (const c of halfUp) {
    lines.push(
      `select extensions.is(public.div_half_up(${c.numerator}::numeric, ${c.denominator}::numeric), ${c.expected}::bigint, ${sqlLiteral(`halfUp ${c.numerator}/${c.denominator}`)});`
    );
  }

  for (const c of convert) {
    lines.push(
      `select extensions.is(public.convert_minor(${c.amount}::bigint, ${sqlString(c.fromPerEur)}::numeric, ${c.fromExponent}, ${sqlString(c.toPerEur)}::numeric, ${c.toExponent}), ${c.expected}::bigint, ${sqlLiteral(`convert: ${c.name}`)});`
    );
  }

  // RD-03: convert_minor_exact's four extra params are nullable numeric -- null for a plain
  // (non-custom) leg, matching per_eur_rate()'s own custom_unit_value/custom_ref_per_eur out
  // params, which are null except for a custom currency's leg.
  const numOrNull = (v) => (v === null ? 'null' : `${sqlString(v)}::numeric`);
  for (const c of convertExact) {
    lines.push(
      `select extensions.is(public.convert_minor_exact(${c.amount}::bigint, ${sqlString(c.fromPerEur)}::numeric, ${c.fromExponent}, ${numOrNull(c.fromCustomUnitValue)}, ${numOrNull(c.fromCustomRefPerEur)}, ${sqlString(c.toPerEur)}::numeric, ${c.toExponent}, ${numOrNull(c.toCustomUnitValue)}, ${numOrNull(c.toCustomRefPerEur)}), ${c.expected}::bigint, ${sqlLiteral(`convertExact: ${c.name}`)});`
    );
  }

  for (const c of customPerEur) {
    lines.push(
      `select extensions.is(public.custom_per_eur(${sqlString(c.referencePerEur)}::numeric, ${sqlString(c.unitValue)}::numeric)::text, ${sqlString(c.expected)}, ${sqlLiteral(`customPerEur: ${c.name}`)});`
    );
  }

  for (const c of crossRate) {
    lines.push(
      `select extensions.is(public.cross_rate(${sqlString(c.fromPerEur)}::numeric, ${sqlString(c.toPerEur)}::numeric)::text, ${sqlString(c.expected)}, ${sqlLiteral(`crossRate: ${c.name}`)});`
    );
  }

  for (const c of exponents) {
    lines.push(
      `select extensions.is(public.currency_exponent(${sqlString(c.code)}, null), ${c.exponent}, ${sqlLiteral(`exponent ${c.code}`)});`
    );
  }

  lines.push('');
  lines.push('select * from extensions.finish();');
  lines.push('rollback;');
  lines.push('');

  // Normalise line endings to \n regardless of platform.
  return lines.join('\n').replace(/\r\n/g, '\n');
}

function main() {
  const checkMode = process.argv.includes('--check');
  const fixtureRaw = readFileSync(FIXTURE_PATH, 'utf8');
  const fixture = JSON.parse(fixtureRaw);
  const generated = generate(fixture);

  if (checkMode) {
    if (!existsSync(OUTPUT_PATH)) {
      console.error(`gen-money-mirror-test --check: ${OUTPUT_PATH} does not exist. Run without --check first.`);
      process.exit(1);
    }
    const onDisk = readFileSync(OUTPUT_PATH, 'utf8').replace(/\r\n/g, '\n');
    if (onDisk !== generated) {
      console.error(
        'gen-money-mirror-test --check: 07_money_rounding_mirror.test.sql is out of date with money-conversion-cases.json.\n' +
          'Run `node scripts/gen-money-mirror-test.mjs` and commit the result.'
      );
      process.exit(1);
    }
    console.log('gen-money-mirror-test --check: up to date.');
    process.exit(0);
  }

  writeFileSync(OUTPUT_PATH, generated);
  console.log(`Wrote ${OUTPUT_PATH}`);
}

main();
